FIGURES = [
    {"id": "H-1", "page": "hub", "section": "paths", "stem": "nephrology-nursing-learning-paths", "w": 1792, "h": 1024, "alt": "Two lanes of twelve module tiles: the Nephrology Nursing path in numerical order and the Hemodialysis Nursing path in its own order, both ending at Module 12.", "caption": "Both paths use the same twelve modules. The Hemodialysis Nursing path moves to the dialysis modules (6 to 9) right after Module 1, and both paths finish with the Module 12 capstone."},
    {"id": "H-2", "page": "educator", "section": "structure", "stem": "nephrology-nursing-teaching-cycle", "w": 1792, "h": 1024, "alt": "Four-stage teaching cycle (mental model, physiology, evidence, bedside) feeding a nursing case framed as Assess, Communicate, Teach, Escalate, then a self-check.", "caption": "Every module moves from a plain-language picture to physiology, evidence, and bedside practice, then applies it in a nursing case (Assess, Communicate, Teach, Escalate) and ends with a self-check quiz with answer rationales."},
    {"id": "01-A", "page": "01", "section": "nephron", "stem": "nephrology-nursing-01-nephron-map", "w": 1792, "h": 1024, "alt": "Enlarged nephron with five labeled segments showing what each reclaims or controls, aldosterone and antidiuretic hormone at the collecting duct, and a small kidney locator.", "caption": "Each nephron filters first, then reclaims most of what it filtered. The table on this page adds the medicines that act at each segment."},
    {"id": "01-B", "page": "01", "section": "tests", "stem": "nephrology-nursing-01-two-kidney-tests", "w": 1792, "h": 1024, "alt": "Side-by-side panels: estimated filtration rate measures how much the kidneys filter; urine albumin-to-creatinine ratio measures leaking, each with caution tags.", "caption": "Estimated glomerular filtration rate (eGFR) shows how much the kidneys filter; the urine albumin-to-creatinine ratio (ACR) shows how much albumin leaks through. Each predicts risk on its own, so a kidney check needs both."},
    {"id": "01-C", "page": "01", "section": "bedside", "stem": "nephrology-nursing-01-focused-renal-assessment", "w": 1792, "h": 1024, "alt": "Eight-step renal assessment from breathing to access site, ending in three judgments: stable, needs review today, or urgent escalation now.", "caption": "Start with breathing, because pulmonary congestion cannot wait. Weight is the most useful single number for fluid, and the assessment is complete only when it ends in a judgment and an action."},
    {"id": "01-D", "page": "01", "section": "balance", "stem": "nephrology-nursing-01-four-balances", "w": 1536, "h": 1152, "alt": "Reference grid for water, sodium, potassium, and acid balance: what the kidney controls, what goes wrong in kidney failure, and the clue to notice.", "caption": "Sodium sets the volume of fluid; water sets the sodium concentration. A swollen patient can have a low serum sodium, and deep, rapid breathing with clear lungs is a reason to check bicarbonate."},
    {"id": "02-A", "page": "02", "section": "causes", "stem": "nephrology-nursing-02-kdigo-risk-grid", "w": 1536, "h": 1152, "alt": "Color-coded grid of filtration by albuminuria categories showing risk level and suggested minimum kidney checks per year in each cell.", "caption": "Each cell gives the risk level and the suggested minimum number of kidney-function and albuminuria checks per year (KDIGO 2024). Sicker or less stable patients are seen more often."},
    {"id": "02-B", "page": "02", "section": "slowing", "stem": "nephrology-nursing-02-slowing-progression-pillars", "w": 1792, "h": 1024, "alt": "Six pillars holding up kidney protection: blood pressure, renin–angiotensin inhibitor, SGLT2 inhibitor, statin, sodium, and avoiding kidney harm, each with one nursing check.", "caption": "Nurses rarely prescribe these treatments, but they check whether each one is in place, tolerated, and restarted after an illness. A creatinine rise of up to 30% after starting a renin–angiotensin inhibitor is expected and is reported, not a reason to stop on its own."},
    {"id": "02-C", "page": "02", "section": "bedside", "stem": "nephrology-nursing-02-staging-at-the-desk", "w": 1024, "h": 1536, "alt": "Six-step workflow: review the trend, check for an acute change, establish chronicity, record cause and categories, reconcile medicines, and arrange monitoring or referral.", "caption": "A possible acute change is assessed promptly first; chronicity is confirmed only in a clinically stable patient, over at least 3 months. The kidney failure risk thresholds are KDIGO 2024 practice points, and local referral criteria may differ."},
    {"id": "03-A", "page": "03", "section": "physiology", "stem": "nephrology-nursing-03-four-disturbances", "w": 1792, "h": 1024, "alt": "Fewer working nephrons lead to anemia, mineral and bone disorder, potassium and acid retention, and poor nutrition, each linked to its body consequence.", "caption": "None of these disturbances announces itself with a dramatic symptom, so they are found by scheduled testing and by asking the right questions at every visit."},
    {"id": "03-B", "page": "03", "section": "mbd-care", "stem": "nephrology-nursing-03-mineral-bone-loop", "w": 1792, "h": 1024, "alt": "Loop showing retained phosphate and low active vitamin D lowering calcium, raising parathyroid hormone, and drawing minerals from bone, with six treatment entry points.", "caption": "Phosphate binders act in the gut and only work when taken with food. Trials show these treatments improve laboratory values more consistently than fractures or survival."},
    {"id": "03-C", "page": "03", "section": "diet", "stem": "nephrology-nursing-03-filipino-food-guide", "w": 1792, "h": 1024, "alt": "Filipino foods higher and lower in potassium, processed foods high in absorbed phosphate, a four-step potassium-lowering method, and protein advice by stage.", "caption": "These are counseling examples, not a complete table; portions and preparation are adjusted to each patient's own potassium and phosphate results. Unintentional weight loss calls for a dietitian, not more restriction."},
    {"id": "03-D", "page": "03", "section": "anemia-care", "stem": "nephrology-nursing-03-anemia-iron-decision", "w": 1024, "h": 1536, "alt": "Flowchart: gather blood count, reticulocytes, ferritin, and TSAT; suspend iron during infection; withhold iron when ferritin exceeds 700 or TSAT reaches 40%.", "caption": "Iron is held when ferritin is above 700 ng/mL or transferrin saturation (TSAT) is 40% or higher, and suspended during active infection (KDIGO 2026). Thresholds for starting iron differ by setting and follow the prescriber and unit protocol."},
    {"id": "04-A", "page": "04", "section": "physiology", "stem": "nephrology-nursing-04-aki-three-causes", "w": 1792, "h": 1024, "alt": "Kidney and urinary tract schematic dividing acute kidney injury causes into reduced blood supply, kidney tissue damage, and blocked urine outflow, with examples.", "caption": "Acute kidney injury is sorted like a slow household tap: the supply, the filter, or the outflow pipe. Reduced perfusion and obstruction are often reversible within hours if someone notices, so check them first."},
    {"id": "04-B", "page": "04", "section": "staging", "stem": "nephrology-nursing-04-aki-staging-card", "w": 1536, "h": 1152, "alt": "Reference card of KDIGO 2012 acute kidney injury definition and stages 1 to 3 by serum creatinine and urine output, with a 60 kg worked example.", "caption": "Any one definition criterion is enough to diagnose acute kidney injury, and the patient is placed in the highest stage reached by either creatinine or urine output. Even stage 1 is reported."},
    {"id": "04-C", "page": "04", "section": "evidence", "stem": "nephrology-nursing-04-hyperkalemia-sequence", "w": 1024, "h": 1536, "alt": "Algorithm showing nursing steps for hyperkalemia: recognize level and ECG, continuous monitoring, immediate SBAR call, prepare ordered treatments, recheck potassium.", "caption": "Emergency hyperkalemia treatment is prescribed; the nurse's time-critical work is recognition, continuous cardiac monitoring, an immediate call, and having ordered treatments ready. Because shifting treatments wear off, a repeat potassium is part of the plan."},
    {"id": "04-D", "page": "04", "section": "acute-krt", "stem": "nephrology-nursing-04-crrt-circuit", "w": 1672, "h": 941, "alt": "Continuous hemofiltration circuit from a right internal jugular dialysis catheter through blood pump and filter, replacement fluid route choice, effluent bag, and nursing watch points.", "caption": "In continuous hemofiltration, blood leaves through the red limb, is pumped up through the filter, and returns through the blue limb; replacement fluid joins one prescribed bloodline point, never the filter&rsquo;s side port. The catheter is drawn as a simple schematic, and the exact setup follows your device and unit."},
    {"id": "05-A", "page": "05", "section": "compare", "stem": "nephrology-nursing-05-four-roads", "w": 1792, "h": 1024, "alt": "Four equal columns comparing in-center hemodialysis, peritoneal dialysis, kidney transplant, and conservative kidney management by where, how often, who does the work, and daily life.", "caption": "Each pathway has its own toll, and none is right for everyone; the nurse's job is to make all four visible in the same level of detail. People often move between pathways over a lifetime."},
    {"id": "05-B", "page": "05", "section": "timing", "stem": "nephrology-nursing-05-preparation-timeline", "w": 1792, "h": 1024, "alt": "Timeline from stage 3 to the start of kidney replacement showing education, vein preservation, transplant referral, fistula, PD catheter, hepatitis B vaccination, and social work.", "caption": "Starting dialysis is a clinical decision made on symptoms and complications, not on a single number, so preparation happens early. An unplanned start through a temporary catheter is associated with more infections, longer hospital stays, and worse early survival."},
    {"id": "05-C", "page": "05", "section": "sdm", "stem": "nephrology-nursing-05-shared-decision", "w": 1792, "h": 1024, "alt": "Three-step shared decision conversation: introduce the choice, describe the options, help the patient weigh them, with nurse phrases and common fears.", "caption": "Shared decision-making runs in three steps, and the decision does not have to be made in one visit. Ask the patient early and privately how much they want to know and who they want involved."},
    {"id": "06-A", "page": "06", "section": "physiology", "stem": "nephrology-nursing-06-transport-processes", "w": 1792, "h": 1024, "alt": "Three panels showing diffusion as a tea bag, ultrafiltration as a coffee press, and convection, each mapped to the dialyzer membrane with driving force and what moves.", "caption": "Diffusion removes urea and potassium down a concentration gradient; ultrafiltration removes water by pressure; convection carries larger solutes along with that water. In the dialyzer, fresh dialysate flows opposite to the blood, so the gradient never runs out."},
    {"id": "06-B", "page": "06", "section": "circuit", "stem": "nephrology-nursing-06-hd-circuit-fistula", "w": 1672, "h": 941, "alt": "Hemodialysis circuit from forearm fistula arterial needle through pressure sensor, blood pump, heparin line, dialyzer, venous chamber, air detector, to venous needle, with countercurrent cutaway.", "caption": "Everything before the blood pump is pulled, so arterial pressure reads below zero; everything after is pushed, so venous pressure reads above zero. Blood and dialysate run in opposite directions through the dialyzer, and the air detector is the last guard before blood returns."},
    {"id": "06-C", "page": "06", "section": "circuit", "stem": "nephrology-nursing-06-pressure-alarms", "w": 1024, "h": 1536, "alt": "Reference card of four hemodialysis pressure alarms (arterial too negative, venous high, venous low, transmembrane high), each with likely causes and first checks.", "caption": "Each alarm is read on its own: find which side of the pump the sensor is on, then look at the patient and the access before touching the machine. The venous pressure alarm cannot be relied on to detect venous needle dislodgement, so the access stays visible for the whole treatment."},
    {"id": "06-D", "page": "06", "section": "dialysate", "stem": "nephrology-nursing-06-dialysate-components", "w": 1536, "h": 1152, "alt": "Reference card of seven dialysate components, sodium to temperature, with what each does and the risks if set too low or too high, including the calcium range.", "caption": "Dialysate is a prescribed drug delivered by the liter: the level set in the bath decides where the patient's blood level ends up. A wrong concentrate on the machine is a medication error and is reported as one."},
    {"id": "07-A", "page": "07", "section": "physiology", "stem": "nephrology-nursing-07-access-types", "w": 1792, "h": 1024, "alt": "Three panels compare an arteriovenous fistula, a graft, and a tunneled catheter by readiness, infection risk, and typical failure.", "caption": "A fistula takes weeks to months to mature but carries the lowest infection risk. A graft is ready sooner, and a tunneled catheter works immediately but has the highest rate of bloodstream infection. The \"rule of 6s\" is a traditional memory aid, not a test the access must pass."},
    {"id": "07-B", "page": "07", "section": "exam", "stem": "nephrology-nursing-07-look-feel-listen", "w": 1792, "h": 1024, "alt": "Infographic of normal fistula findings by look, feel, and listen, with six warning patterns, each paired with the nurse's action.", "caption": "A healthy fistula is soft, with a continuous thrill and a low-pitched continuous bruit. Each warning pattern points to a likely problem and an action, almost always to report it. A newly absent thrill and bruit means do not cannulate and notify the nephrologist promptly."},
    {"id": "07-C", "page": "07", "section": "cannulation", "stem": "nephrology-nursing-07-cannulation-techniques", "w": 1792, "h": 1024, "alt": "Three panels compare rope-ladder, area puncture, and buttonhole cannulation, with a strip showing needle direction and spacing along a fistula.", "caption": "Rope-ladder rotation spreads wear evenly and is the default for fistulas and the only technique for grafts. Area puncture balloons the vein into aneurysms. Buttonhole carries a higher infection risk and is limited to selected situations. The venous needle always points with the flow, toward the heart, and the two tips are kept well apart."},
    {"id": "07-D", "page": "07", "section": "catheters", "stem": "nephrology-nursing-07-catheter-care-sequence", "w": 1792, "h": 1024, "alt": "Step sequence for tunneled catheter connection and exit-site care, with two stop conditions: suspected catheter displacement and a break in asepsis.", "caption": "Organisms reach the blood mainly through the inside of the catheter, so hub care matters most. Stop if the catheter may have moved or if asepsis is broken; then follow the procedure and report. Antiseptic, scrub time, and lock solution follow unit procedure and the order."},
    {"id": "08-A", "page": "08", "section": "components", "stem": "nephrology-nursing-08-water-treatment-train", "w": 1792, "h": 1024, "alt": "Water treatment train from supply through filters, softener, two carbon tanks, reverse osmosis, and distribution loop to the dialysis machine, with failures and monitors.", "caption": "Carbon is the only barrier against chlorine and chloramine, and it gives no warning when exhausted, so total chlorine is tested after the carbon every treatment day. A machine showing normal conductivity and temperature can still be running on unsafe water. Sampling points and limits follow the unit water plan."},
    {"id": "08-B", "page": "08", "section": "syndromes", "stem": "nephrology-nursing-08-contaminant-syndromes", "w": 1536, "h": 1152, "alt": "Reference card with the cluster rule at center, surrounded by nine water contaminants and the symptoms each causes in patients.", "caption": "The nurse never sees a contaminant, only a patient with a symptom. One patient with chills usually has a patient-level cause. Two or more patients on the same shift with the same new symptom share an exposure, so stop connecting patients and investigate the common source first."},
    {"id": "08-C", "page": "08", "section": "disinfect-reuse", "stem": "nephrology-nursing-08-reprocessing-checkpoints", "w": 1792, "h": 1024, "alt": "Six safety checkpoints for a reprocessed dialyzer, from label and two-person identity check to the germicide absence test before priming.", "caption": "Each check answers a specific hazard: the validated disinfection process is verified, germicide presence before rinsing proves disinfection happened, and germicide absence after rinsing meets the release criterion. Any failed or missing check means the dialyzer is not used and the event is reported."},
    {"id": "09-A", "page": "09", "section": "physiology", "stem": "nephrology-nursing-09-session-three-phases", "w": 1792, "h": 1024, "alt": "Three-phase timeline of a dialysis session with nursing checks before, during, and after, plus findings that require a call before connecting.", "caption": "The pre-treatment assessment ends in one decision: start as prescribed, or call the physician first. During treatment, a half-minute round at each station checks the face, the access, the lines, and the machine. A patient leaves only when the discharge checks are met. All numeric thresholds come from unit policy or standing orders."},
    {"id": "09-B", "page": "09", "section": "bedside", "stem": "nephrology-nursing-09-idh-algorithm", "w": 1024, "h": 1536, "alt": "Algorithm for hypotension during dialysis: recognize, stop fluid removal, position, assess, notify, then escalate if no prompt recovery; prevention strategies alongside.", "caption": "Stopping fluid removal and raising the legs address the usual mechanism, and every further step follows protocol or order. Hypotension that does not correct promptly, or that comes with chest pain, arrhythmia, or altered consciousness, is treated as an emergency. A recurring pattern is a prescription problem to report."},
    {"id": "09-C", "page": "09", "section": "bedside", "stem": "nephrology-nursing-09-chairside-emergencies", "w": 1536, "h": 1152, "alt": "Reference card of five dialysis emergencies (air entry, hemolysis, needle dislodgement, dialyzer reaction, disequilibrium), each with signs and first actions.", "caption": "In every emergency, call for help early, stay with the patient, and record the onset time. In hemolysis and severe dialyzer reactions the blood in the circuit is not returned, and blood is never returned through a line that contains air. Oxygen, positioning, and further steps follow the unit&rsquo;s emergency protocol."},
    {"id": "10-A", "page": "10", "section": "membrane", "stem": "nephrology-nursing-10-pd-membrane", "w": 1792, "h": 1024, "alt": "Diagram of the peritoneal capillary wall with two kinds of opening, the fading glucose pull, and the shapes of fast and slow transporter curves.", "caption": "Water and small solutes cross the peritoneal capillary wall through gaps between cells, and water alone crosses through tiny water-only channels. Glucose leaks back into the blood, so the pull on water fades. This happens sooner in fast transporters, which is why they do better with short dwells."},
    {"id": "10-B", "page": "10", "section": "exchange", "stem": "nephrology-nursing-10-pd-exchange", "w": 1792, "h": 1024, "alt": "Five-step twin-bag peritoneal dialysis exchange shown as labeled flow paths (connect, drain, flush, fill, disconnect), with the reason for each step and how to record net removal.", "caption": "The flush comes before the fill because it carries any organisms picked up at the connection away to the drain bag before fluid flows toward the abdomen. Net fluid removal equals the volume drained minus the volume filled."},
    {"id": "10-C", "page": "10", "section": "infection", "stem": "nephrology-nursing-10-peritonitis-algorithm", "w": 1024, "h": 1536, "alt": "Five-step card for suspected PD peritonitis: contact the team now, assess and collect specimens, the three diagnostic criteria, prompt treatment, and reassessment.", "caption": "Cloudy fluid or abdominal pain means contacting the PD team now. Peritonitis is diagnosed when at least two of three criteria are met; specimens are collected before antibiotics when feasible, and prescribed treatment starts without waiting for culture results."},
    {"id": "11-A", "page": "11", "section": "physiology", "stem": "nephrology-nursing-11-transplant-anatomy", "w": 1792, "h": 1024, "alt": "Lower-abdomen diagram of a transplanted kidney joined to a pelvic artery, pelvic vein and bladder with a stent, labeled with each site's warning sign.", "caption": "The new kidney is placed in the lower abdomen and joined to the pelvic vessels and the bladder. Each join has its own complication. Because the graft has no nerve supply, a blocked ureter is often painless, and a clot in the artery can stop urine abruptly."},
    {"id": "11-B", "page": "11", "section": "complications", "stem": "nephrology-nursing-11-transplant-infection-timeline", "w": 1792, "h": 1024, "alt": "Three-window timeline of infections after kidney transplant (first month, months 1 to 6, after 6 months) with the nursing focus for each window.", "caption": "Infection risk follows the level of immunosuppression. Opportunistic infections peak in months 1 to 6 and come back whenever immunosuppression is increased to treat rejection. Fever in a recipient is always reported the same day."},
    {"id": "11-C", "page": "11", "section": "drugs", "stem": "nephrology-nursing-11-immunosuppressant-card", "w": 1536, "h": 1152, "alt": "Reference card of six transplant immunosuppressants showing what each does, side effects to ask about, and interactions to guard against. Shows no doses or levels.", "caption": "A vigilance card, not a prescribing guide. Doses and blood levels are set by the transplant team, and no new medicine, supplement or herbal product is started until the team has checked it."},
    {"id": "12-A", "page": "12", "section": "dashboard", "stem": "nephrology-nursing-12-pdsa-cycle", "w": 1792, "h": 1024, "alt": "Four-part Plan–Do–Study–Act cycle on early-ending afternoon sessions, with aim, measure and decision. All figures are labeled illustrative.", "caption": "A worked example with invented figures. One small change was tested on one shift for two weeks, measured weekly, and then kept and extended, and a second cycle began on cramps."},
    {"id": "12-B", "page": "12", "section": "dashboard", "stem": "nephrology-nursing-12-quality-dashboard", "w": 1536, "h": 1152, "alt": "Grid of ten dialysis-unit quality domains, each with example measures and no targets, plus the infection rate formula per 100 patient-months.", "caption": "A unit dashboard tracks a small set of measures every month. Each target comes from the guideline the unit has adopted and is set by the medical director. Accurate nursing records are where these reports begin."},
    {"id": "12-C", "page": "12", "section": "readiness", "stem": "nephrology-nursing-12-typhoon-readiness", "w": 1792, "h": 1024, "alt": "Three-phase typhoon readiness sequence for a dialysis unit (before, during, after) with the nurse's tasks and patient teaching for missed dialysis.", "caption": "Survival after a disaster is mostly arranged before it. Patients are dialyzed early when the nephrologist orders it, every patient is accounted for by name afterward with clinical urgency guiding who is dialyzed first, and treatment restarts only after the water system has been recommissioned and tested."},
    {"id": "12-D", "page": "12", "section": "teamwork", "stem": "nephrology-nursing-12-delegation", "w": 1792, "h": 1024, "alt": "Comparison of tasks a nurse may delegate in a dialysis unit, subject to authorization, training, policy, and supervision, and the judgments that stay with the registered nurse.", "caption": "A nurse may hand a task, not a judgment, to a trained and authorized technician or assistant under unit policy and supervision. Assessment, the decision to start, and evaluation of the response stay with the nurse, and so does the signature."},
    {"id": "13-A", "page": "13", "section": "physiology", "stem": "nephrology-nursing-13-convection-sieving", "w": 1792, "h": 1024, "alt": "Diffusion, ultrafiltration, and convection across a filter fiber wall, with sieving coefficients near one for urea, lower for larger molecules, near zero for albumin.", "caption": "Diffusion moves small solutes down a concentration difference; convection drags solutes of any size up to the pore limit along with water pushed through by pressure. Each solute's sieving coefficient says how freely it crosses."},
    {"id": "13-B", "page": "13", "section": "physiology", "stem": "nephrology-nursing-13-pre-post-dilution", "w": 1792, "h": 1024, "alt": "Pre-dilution versus post-dilution replacement fluid compared, with the worked filtration fraction: 35 mL/min removed from 140 mL/min plasma flow equals 25%.", "caption": "Replacement fluid given before the filter keeps blood thinner and the filter alive longer, at some cost in clearance; given after, every liter removed is the patient's own plasma water, but blood thickens in the fibers. The filtration fraction measures how hard the filter is working."},
    {"id": "13-C", "page": "13", "section": "crrt-modes", "stem": "nephrology-nursing-13-crrt-modes", "w": 1536, "h": 1152, "alt": "Reference card comparing SCUF, CVVH, CVVHD, and CVVHDF by fluids used, mechanism, what each removes best, and why chosen, with SLED as the prolonged alternative.", "caption": "The name of the mode tells you which pumps are running, and therefore which fluids, bags, and checks apply. Every mode can also remove fluid, and no mode has proven survival benefit over another."},
    {"id": "13-D", "page": "13", "section": "crrt-anticoag", "stem": "nephrology-nursing-13-cvvhdf-citrate-circuit", "w": 1672, "h": 941, "alt": "CVVHDF circuit from a jugular dialysis catheter: citrate enters the red access line, dialysate runs countercurrent, replacement fluid joins one blood line, calcium returns separately.", "caption": "Citrate enters the blood line just after it leaves the patient and binds calcium so the circuit cannot clot; much of it leaves in the effluent, and calcium is replaced into the patient by a separate infusion. Dialysate runs outside the fibers against the blood; replacement fluid joins the blood line itself."},
    {"id": "13-E", "page": "13", "section": "crrt-anticoag", "stem": "nephrology-nursing-13-citrate-watch", "w": 1024, "h": 1536, "alt": "Citrate anticoagulation algorithm: how citrate works, two calcium samples, and the signs of low calcium, accumulation, and excess, each ending in report per protocol.", "caption": "Two calcium samples answer two questions: is the circuit anticoagulated, and is the patient safe. Low calcium, citrate accumulation, and citrate excess each have a recognizable pattern; the nurse checks the infusions and reports, and targets and adjustments come from the protocol."},
    {"id": "13-F", "page": "13", "section": "crrt-fluid", "stem": "nephrology-nursing-13-three-fluid-numbers", "w": 1536, "h": 1152, "alt": "Machine net removal, patient total balance, and prescribed goal compared, with a worked hour where the machine removes 250 mL yet the patient is 50 mL short.", "caption": "The machine counts only its own fluids; it knows nothing about the infusions, the feed, or the urine bag. Record all three numbers every hour and report when they drift apart or the patient cannot tolerate removal."},
    {"id": "13-G", "page": "13", "section": "crrt-circuit", "stem": "nephrology-nursing-13-crrt-pressure-alarms", "w": 1024, "h": 1536, "alt": "Continuous therapy alarm algorithm: access, return, pre-filter and transmembrane trends, air and blood leak alarms, each mapped to likely cause, first check, and escalation.", "caption": "Look at the patient before the machine. Rising transmembrane pressure or pressure drop predicts clotting hours ahead, which gives time to report and plan a change with blood return; air and blood-leak detectors are never overridden."},
    {"id": "13-H", "page": "13", "section": "crrt-complications", "stem": "nephrology-nursing-13-crrt-complications-watch", "w": 1536, "h": 1152, "alt": "Watch table for continuous therapy: hypothermia, electrolyte losses, acid–base, bleeding, catheter problems, drug removal, nutrition, low platelets, each with signs and action.", "caption": "Continuous clearance does not choose what it removes: heat, electrolytes, nutrients, and medicines leave as steadily as urea and potassium. Notice the trend and report it; replacement and dosing come from the prescriber, pharmacist, and dietitian."},
    {"id": "13-I", "page": "13", "section": "hdf-principles", "stem": "nephrology-nursing-13-online-hdf-fluid-path", "w": 1792, "h": 1024, "alt": "Online HDF fluid path: treated water and concentrates become dialysate, pass two ultrafilters, and enter the venous blood line after a high-flux dialyzer.", "caption": "In online HDF the machine filters its own dialysate twice: once to make ultrapure dialysate for the dialyzer, and again to make sterile substitution fluid that runs straight into the blood. That is why the substitution line is handled like an intravenous line."},
    {"id": "13-J", "page": "13", "section": "hdf-prescription", "stem": "nephrology-nursing-13-convection-volume-arithmetic", "w": 1792, "h": 1024, "alt": "Convection volume equals substitution plus net ultrafiltration; worked example shows how lower blood flow or a shorter session drops 23 liters to 19.4 or 17.8.", "caption": "Convection volume is everything filtered across the membrane: the substitution volume plus the net ultrafiltration. With the same fraction of blood flow, a weaker access or a shorter session misses the target even though the substitution setting never changed."},
    {"id": "13-K", "page": "13", "section": "hdf-evidence", "stem": "nephrology-nursing-13-hdf-trials", "w": 1536, "h": 1152, "alt": "Six HDF studies compared: CONTRAST, Turkish, ESHOL, CONVINCE, and two pooled analyses, with patients, comparator, and result; volume link shown as association.", "caption": "The trials that delivered lower convection volumes found no overall survival difference; CONVINCE randomized only patients able to receive high volumes and found lower mortality. The link between higher achieved volume and better survival is an association, not proof."},
    {"id": "13-L", "page": "13", "section": "hdf-session", "stem": "nephrology-nursing-13-hdf-alarms", "w": 1024, "h": 1536, "alt": "Algorithm for six HDF alarms: transmembrane pressure, substitution fault, blood leak, conductivity, filtration fraction limit, failed ultrafilter test, with first checks and escalation.", "caption": "Find the cause before resetting any alarm, and never widen a limit to keep the session running. A blood leak or a failed ultrafilter test always goes to the charge nurse and the physician or technician."},
    {"id": "H-3", "page": "hub", "section": "progression", "stem": "nephrology-nursing-competency-levels", "w": 1792, "h": 1024, "alt": "Pyramid of four levels: Knows, Shows how, Does supervised, Does independent; clinical assessment thread rises from Module 1 to Module 9.", "caption": "Each level is verified by someone other than the learner, except Knows, which self-study can reach. Clinical assessment climbs from explaining fluid balance in Module 1 to completing treatment assessments independently, after sign-off, in Module 9."},
    {"id": "14-A", "page": "14", "section": "adaptation", "stem": "nephrology-nursing-14-adaptation-over-time", "w": 1792, "h": 1024, "alt": "Adaptation to dialysis drawn as a winding path from shock and grief to working acceptance, with life events that send the patient back, and the tasks and strengths that help.", "caption": "Most patients move back and forth between shock, grief, anger, bargaining, resignation, and a working acceptance, and they move again when something changes. A patient who seemed settled for two years can be in crisis this month."},
    {"id": "14-B", "page": "14", "section": "screening", "stem": "nephrology-nursing-14-screening-to-referral", "w": 1024, "h": 1536, "alt": "Screening pathway: check the patient is alert and stable, explain and give privacy, then report a positive score the same day, act at once on any self-harm answer, and report concern even after a negative screen.", "caption": "A score is a screen, not a diagnosis. A positive answer about death or self-harm overrides the total score, and a questionnaire never overrules a nurse's own worry. A referral that is never completed helps no one, so ask at the next session."},
    {"id": "14-C", "page": "14", "section": "physiology", "stem": "nephrology-nursing-14-delirium-depression-dementia", "w": 1536, "h": 1152, "alt": "Delirium, depression, and dementia compared by onset, course, attention, typical causes in dialysis patients, and nursing response; delirium is an emergency until explained.", "caption": "A new change in alertness or attention is treated as delirium, and therefore as a physical problem, until a physician has assessed it. The three conditions can occur together, and each makes the others harder to recognize."},
    {"id": "14-D", "page": "14", "section": "deescalation", "stem": "nephrology-nursing-14-de-escalation-steps", "w": 1024, "h": 1536, "alt": "Eight de-escalation steps from safety and space and a body check to setting limits and knowing when to stop, with a list of what not to do.", "caption": "Check the body before judging the person: a glucose, a blood pressure, and an oxygen saturation take less than two minutes. Stopping treatment, restraint, sedation, or transfer are physician decisions under facility policy, never a nurse's improvised response."},
    {"id": "14-E", "page": "14", "section": "exercise", "stem": "nephrology-nursing-14-exercise-falls-safety", "w": 1792, "h": 1024, "alt": "Left, the safety screen before exercise during dialysis with reasons not to start or to stop; right, the post-dialysis hour with sitting up, standing with support, and home fall-prevention tips.", "caption": "Exercise makes patients stronger and helps them walk farther and stay independent; trials have not shown that it lowers mortality. The hour after dialysis is the most dangerous time of the week for a fall, so rise in stages and report repeated dizziness."},
    {"id": "14-F", "page": "14", "section": "symptoms", "stem": "nephrology-nursing-14-symptom-burden-recovery", "w": 1792, "h": 1024, "alt": "The recovery-time question at the center of seven common dialysis symptoms, with a loop from asking and rating to reporting, treatment by the physician, rechecking, and telling the patient.", "caption": "\"How long does it take you to recover from a dialysis session?\" A recovery time of more than 12 hours has been associated with poorer quality of life and higher risks of hospitalization and death. A questionnaire that is filed and never acted on teaches patients not to bother answering."},
    {"id": "15-A", "page": "15", "section": "physiology", "stem": "nephrology-nursing-15-filtration-barrier", "w": 1792, "h": 1024, "alt": "Three layers of the glomerular filter, capillary lining, basement membrane, and podocytes with slit diaphragms, shown healthy, leaking albumin when foot processes flatten, and bleeding red cells when inflamed.", "caption": "Blood is separated from urine by three layers that work together. When podocyte foot processes flatten, albumin escapes (the nephrotic pattern); when immune attack damages the capillary wall, red cells escape and filtration falls (the nephritic pattern)."},
    {"id": "15-B", "page": "15", "section": "model", "stem": "nephrology-nursing-15-nephrotic-vs-nephritic", "w": 1792, "h": 1024, "alt": "Nephrotic and nephritic patterns compared: urine, blood tests, swelling, blood pressure, kidney function, main dangers, and typical diseases, with a note that real patients can show a mixture.", "caption": "The two patterns are a starting point for thinking, not a diagnosis; lupus, for example, can leak and bleed at once. The diagnosis usually needs blood tests and often a kidney biopsy."},
    {"id": "15-C", "page": "15", "section": "biopsy", "stem": "nephrology-nursing-15-kidney-biopsy-timeline", "w": 1792, "h": 1024, "alt": "Kidney biopsy nursing timeline: checks before, positioning and specimens during, bed rest and observation after, discharge teaching, and a red-flag band of bleeding signs to report at once.", "caption": "The main risk of a kidney biopsy is bleeding. Most bleeds are small and stop by themselves; careful preparation and close observation in the first hours keep small bleeds small and catch large ones early."},
    {"id": "15-D", "page": "15", "section": "immunosuppression", "stem": "nephrology-nursing-15-immunosuppression-watch", "w": 1536, "h": 1152, "alt": "Watch-list card for glucocorticoids, cyclophosphamide, mycophenolate, rituximab, calcineurin inhibitors, and hydroxychloroquine, with a before-the-first-dose safety checklist and teaching for life on immunosuppression.", "caption": "The benefits and the main dangers of these medicines come from the same action, damping the immune system. The nurse never starts, stops, or adjusts them, but checks, teaches, and reports, and may hold a dose and call when the protocol says so."},
    {"id": "15-E", "page": "15", "section": "diabetic-pkd", "stem": "nephrology-nursing-15-pkd-inheritance", "w": 1792, "h": 1024, "alt": "Family tree showing that each child of a parent with polycystic kidney disease has a one-in-two chance of inheriting the gene, with the nurse's five family-screening steps and key teaching points.", "caption": "Each child of an affected parent has a one-in-two chance of inheriting the gene, and the chance is the same for every child. A relative who carries the gene can still benefit from early blood pressure control and kidney protection."},
    {"id": "16-A", "page": "16", "section": "model", "stem": "nephrology-nursing-16-two-tracks", "w": 1792, "h": 1024, "alt": "Two parallel tracks from diagnosis onward: disease-directed treatment and supportive care, with the balance shifting over time toward comfort for some patients, and the three terms supportive, palliative, and end-of-life care defined.", "caption": "Supportive care starts at diagnosis and runs alongside dialysis, peritoneal dialysis, or a transplant, not after them. For some patients the balance shifts toward comfort; for some the disease-directed track ends, and supportive care becomes all of care."},
    {"id": "16-B", "page": "16", "section": "symptoms-pc", "stem": "nephrology-nursing-16-symptom-wheel", "w": 1536, "h": 1152, "alt": "Symptom wheel with eight segments, pain, itch, breathlessness, nausea and appetite, fatigue, restlessness, low mood, and sleep, each with the nursing comfort measure, around the steps ask, rate, comfort, report, and reassess.", "caption": "For every symptom the pattern is the same: ask, rate it from 0 to 10, relieve what nursing can relieve, report with enough detail for the physician to act, and reassess. After any new symptom medicine, watch for drowsiness, confusion, twitching, and slowed breathing."},
    {"id": "16-C", "page": "16", "section": "acp", "stem": "nephrology-nursing-16-advance-care-planning", "w": 1792, "h": 1024, "alt": "Seven advance care planning steps from opening the topic to reviewing the plan, each with the nurse's part, plus a band on Filipino family and faith and a note that facility policy governs written plans.", "caption": "Advance care planning is a series of conversations, not a single form, and it is revisited whenever health changes. Resuscitation status becomes an order only when the physician writes it."},
    {"id": "16-D", "page": "16", "section": "withdrawal", "stem": "nephrology-nursing-16-request-to-stop-pathway", "w": 1024, "h": 1536, "alt": "Pathway after a request to stop dialysis: listen, screen mood and safety, look for reversible causes, inform the nephrologist the same day, capacity assessment and family meeting with options, then respect the decision and continue care.", "caption": "A request is the start of a conversation, not a decision. An adult with capacity may decide to stop dialysis, and the nurse's duty is to make sure the decision is informed, voluntary, and documented, and that stopping dialysis never means stopping care."},
    {"id": "17-A", "page": "17", "section": "physiology", "stem": "nephrology-nursing-17-working-memory-chunking", "w": 1792, "h": 1024, "alt": "Working memory drawn as a narrow doorway into the large room of long-term memory: a list of ten instructions jams at the door, while two or three familiar bundles pass through; fear, pain, poor sleep, and noise narrow the doorway.", "caption": "Adults can hold only about four meaningful chunks in mind at once. Two or three points per session, linked to what the patient already knows, pass the doorway; retrieval through teach-back and repetition across sessions keep them easy to find."},
    {"id": "17-B", "page": "17", "section": "bedside", "stem": "nephrology-nursing-17-teach-back-loop", "w": 1536, "h": 1152, "alt": "Teach-back loop: choose the moment, teach one goal in two or three points, ask the patient to explain in their own words, re-explain differently if there is a gap, document the learning, and ask again next session.", "caption": "Teach-back checks the teacher; it is never an examination of the patient. If the answer has a gap, re-explain in a different way, not louder and not in the same words, and ask again; then ask once more at the next session."},
    {"id": "17-C", "page": "17", "section": "reading-evidence", "stem": "nephrology-nursing-17-absolute-relative-risk", "w": 1792, "h": 1024, "alt": "Two grids of 100 people: 14.5 had the main outcome with placebo and 9.2 with dapagliflozin; about 5 fewer per 100, a 37% relative reduction, and about 19 treated to prevent one event.", "caption": "A relative reduction sounds the same whatever a patient's starting risk; the absolute benefit depends on it. When explaining benefit to patients, say the absolute figure as a frequency: \"about 5 in 100 people.\""},
    {"id": "17-D", "page": "17", "section": "ebp", "stem": "nephrology-nursing-17-ebp-cycle-pico", "w": 1792, "h": 1024, "alt": "Evidence-based practice cycle: ask a PICO question, search, appraise, apply with judgment and the patient, and evaluate locally, then share; with a worked PICO for fluid teaching and a research-or-improvement checkpoint.", "caption": "Evidence-based practice combines the best current evidence with clinical expertise and the patient's values. A change in a nursing routine goes through the nurse manager; any change to treatment needs an order; and work designed to produce knowledge beyond the unit needs ethics review before it starts."},
    {"id": "03-E", "page": "03", "section": "hd-meals", "stem": "nephrology-nursing-03-hd-day-plate", "w": 1792, "h": 1024, "alt": "A Filipino dialysis-day plate with measured rice, a palm-sized portion of fish or egg, and a lower-potassium vegetable, with swaps for salty and processed foods, a small cup of sabaw counted as fluid, and the binder taken with the first spoonful.", "caption": "On hemodialysis, protein needs go up while salt, potassium, and phosphate still count every day. Change the portion, the preparation, or one ingredient at a time, starting from what the patient ate yesterday; the renal dietitian sets the individual plan."},
    {"id": "07-E", "page": "07", "section": "tb", "stem": "nephrology-nursing-07-cough-triage-airborne", "w": 1792, "h": 1024, "alt": "Floor plan of an open dialysis unit with the coughing patient masked and seated at the far station near an exhaust fan, staff in fitted respirators, beside the steps from screening at the door to the physician's plan.", "caption": "A mask on the coughing patient is the single most useful immediate step. Where and when the patient is dialyzed, and when precautions end, are decided by the physician and the infection-control officer; tuberculosis is not spread through the blood circuit, so standard machine cleaning applies."},
    {"id": "07-F", "page": "07", "section": "vaccination", "stem": "nephrology-nursing-07-vaccination-record", "w": 1792, "h": 1024, "alt": "A sample vaccination register with hepatitis B, influenza, pneumococcal, and COVID-19 rows, beside the hepatitis B path: series, antibody check, responder or second series, yearly check, and booster below 10 mIU/mL.", "caption": "A vaccination program fails quietly, through missing dates rather than dramatic errors. A register with antibody results, a monthly due list, recorded declinations, and a card the patient carries keep doses from being missed or repeated."},
    {"id": "09-D", "page": "09", "section": "hd-drugs", "stem": "nephrology-nursing-09-hd-drug-timing", "w": 1792, "h": 1024, "alt": "Dialysis-day timeline from home before the session, through the start, during, and end of treatment, to home afterward, showing when each medicine class is usually given and the nurse's check for each.", "caption": "Dose, route, and timing always come from the current order, and products differ. Removal by dialysis depends on the drug, not the class, so confirm timing against the order rather than a general rule."},
    {"id": "09-E", "page": "09", "section": "monthly-labs", "stem": "nephrology-nursing-09-monthly-lab-actions", "w": 1536, "h": 1152, "alt": "Monthly laboratory panel card: rules for drawing samples, then each test with what it shows and the nurse's first action, with critical values reported at once and trends read across three months.", "caption": "One result is a point; three results are a direction. Critical values do not wait for the monthly round, and a result reviewed with no recorded decision is a gap in the record."},
    {"id": "09-F", "page": "09", "section": "diabetes-hd", "stem": "nephrology-nursing-09-glucose-dialysis-day", "w": 1792, "h": 1024, "alt": "Blood glucose as a tank with a tap and a drain, showing why insulin lasts longer and less glucose is made in kidney failure, and a dialysis-day timeline where the dialysate buffers glucose during treatment and lows appear afterward.", "caption": "During the session, glucose is pulled toward the dialysate level; after it ends, that buffer is gone, which is one reason low readings appear on the way home or in the evening. Glycated hemoglobin tends to read lower than the true average on dialysis."},
    {"id": "10-D", "page": "10", "section": "home-hd-training", "stem": "nephrology-nursing-10-home-hd-training", "w": 1792, "h": 1024, "alt": "Home hemodialysis training pathway: eight curriculum areas with sign-off, home water, drainage, and electricity checks, first treatments at home with a nurse, remote monitoring triggers, and retraining triggers that loop back.", "caption": "Readiness is shown, not told: the trainee performs the whole treatment, and the care partner can recognize trouble, stop safely, and call. Any change in the house, the machine, the care partner, or the patient's health sends the pathway back to training."},
    {"id": "11-D", "page": "11", "section": "pregnancy", "stem": "nephrology-nursing-11-pregnancy-dialysis-care-map", "w": 1792, "h": 1024, "alt": "Care map for pregnancy on hemodialysis: shared nephrology and obstetric care at the center, with more dialysis and different chemistry, gentle fluid removal, nutrition, anemia, fetal monitoring, medicine review, preeclampsia warning signs, and care after delivery.", "caption": "When a woman on hemodialysis becomes pregnant, dialysis is intensified by the nephrologist and care is shared with obstetrics. A lower threshold to report is right, because blood pressure and urine protein may already be abnormal."},
    {"id": "11-E", "page": "11", "section": "pediatric", "stem": "nephrology-nursing-11-pediatric-vs-adult", "w": 1536, "h": 1152, "alt": "Child and adult compared on causes of kidney disease, fluid rules, the share of blood in the circuit, signs of low blood pressure, blood pressure readings, medicine doses, and dialysis choice, with the worked example that half a kilogram in a 10-kg child equals 3.5 kg in a 70-kg adult.", "caption": "Every quantity that is routine in an adult becomes large in proportion in a small child, so fluid status is judged as a percentage of body weight. Prescriptions and settings for children belong to pediatric nephrology teams."},
    {"id": "12-E", "page": "12", "section": "conduct", "stem": "nephrology-nursing-12-professional-boundaries", "w": 1536, "h": 1152, "alt": "Seven scenario cards, a cash gift, a photo on social media, a corridor handoff, a supplier's gift, false audit records, a senior nurse ridiculing a new nurse, and a herbal tea, each paired with the professional response.", "caption": "Warmth toward patients is part of good care; a personal or financial relationship is not. Covering for a colleague is not loyalty, and cultural humility means asking about a remedy without ridicule."},
    {"id": "12-F", "page": "12", "section": "disaster", "stem": "nephrology-nursing-12-emergency-kit", "w": 1792, "h": 1024, "alt": "A waterproof dialysis emergency bag laid out with its contents: the dialysis information card, medicine list and reserve, emergency-diet foods and a measured cup, flashlight, power bank, and cash, plus extra items for diabetes and for peritoneal dialysis.", "caption": "A disaster is dangerous to a dialysis patient when it breaks any link (travel, staff, power, water, or supplies) for longer than the patient can safely wait. A ready bag by the door, with dated serology results on paper, lets another unit treat the patient safely on the first session."},
    {"id": "12-G", "page": "12", "section": "disaster-drill", "stem": "nephrology-nursing-12-disaster-drill-cycle", "w": 1792, "h": 1024, "alt": "Disaster drill cycle: tabletop, functional, and full drills, the roles assigned by position, a blame-free after-action review with four questions, and actions with an owner and a date that the next drill checks.", "caption": "A plan that has never been tested is a hope. Every action from the review gets a named owner and a date, and the next drill checks whether it was done; real patients are never placed at risk to make a drill realistic."},
    {"id": "13-M", "page": "13", "section": "tpe-principles", "stem": "nephrology-nursing-13-plasma-separation-methods", "w": 1792, "h": 1024, "alt": "Centrifugal and membrane plasma separation compared: a spinning chamber layers cells outward and draws plasma off, and a plasma filter lets plasma through its pores; removed plasma goes to waste and albumin or donor plasma is returned with the cells.", "caption": "A dialyzer keeps proteins in the blood; plasma exchange removes the plasma itself, with the antibodies and other large proteins dissolved in it, and replaces it. Neither separation method has been shown to be better for patients in general."},
    {"id": "13-N", "page": "13", "section": "tpe-nursing", "stem": "nephrology-nursing-13-plasma-exchange-watch", "w": 1024, "h": 1536, "alt": "Plasma exchange watch algorithm: checks before the session, then early and late signs of citrate-related low calcium, low blood pressure, allergic reaction to plasma, and bleeding, each with first actions and reporting, and the record after the session.", "caption": "Early citrate symptoms are things the patient feels, so a patient taught to say \"tingling\" at once is the first alarm. The nurse watches the patient more than the machine and acts per order and protocol; severe signs are an emergency."},
]
